def blockify(grid):
    """Split grid into blocks separated by full divider lines/cols; return blocks with index ranges."""
    h,w=len(grid),len(grid[0])
    rdiv=[i for i in range(h) if all(v==8 for v in grid[i])]
    cdiv=[j for j in range(w) if all(grid[i][j]==8 for i in range(h))]
    def segs(divs,n):
        s=[];prev=-1
        for d in divs+[n]:
            if d-1>prev: s.append((prev+1,d))
            prev=d
        return s
    return segs(rdiv,h),segs(cdiv,w)

def transform(grid):
    out=[row[:] for row in grid]
    rb,cb=blockify(grid)
    seeds={}
    for bi,(r0,r1) in enumerate(rb):
        for bj,(c0,c1) in enumerate(cb):
            for i in range(r0,r1):
                for j in range(c0,c1):
                    if grid[i][j]!=0:
                        seeds.setdefault(grid[i][j],[]).append((bi,bj))
                        for ii in range(r0,r1):
                            for jj in range(c0,c1):
                                out[ii][jj]=grid[i][j]
    for col,bs in seeds.items():
        rows_b=sorted({b[0] for b in bs}); cols_b=sorted({b[1] for b in bs})
        if len(rows_b)>=2 and len(cols_b)==1:  # vertical alignment
            for bi in range(rows_b[0],rows_b[-1]+1):
                r0,r1=rb[bi]; c0,c1=cb[cols_b[0]]
                for i in range(r0,r1):
                    for j in range(c0,c1):
                        if out[i][j]!=8: out[i][j]=col if out[i][j] in (0,col) else 6
        if len(cols_b)>=2 and len(rows_b)==1:
            for bj in range(cols_b[0],cols_b[-1]+1):
                r0,r1=rb[rows_b[0]]; c0,c1=cb[bj]
                for i in range(r0,r1):
                    for j in range(c0,c1):
                        if out[i][j]!=8: out[i][j]=col if out[i][j] in (0,col) else 6
    return out

