from collections import defaultdict
def transform3(grid):
    """Two+ same-color seeds sharing a tile-column fill tiles between them vertically (same tile-row: horizontally); crossings -> 6."""
    out=[row[:] for row in grid]
    rb,cb=blockify(grid)
    bycol=defaultdict(list); byrow=defaultdict(list)
    for bi,(r0,r1) in enumerate(rb):
        for bj,(c0,c1) in enumerate(cb):
            for i in range(r0,r1):
                for j in range(c0,c1):
                    if grid[i][j]!=0:
                        bycol[(grid[i][j],bj)].append(bi)
                        byrow[(grid[i][j],bi)].append(bj)
    def fill(bi,bj,col):
        r0,r1=rb[bi]; c0,c1=cb[bj]
        for i in range(r0,r1):
            for j in range(c0,c1):
                if out[i][j]!=8: out[i][j]=col if out[i][j] in (0,col) else 6
    for (col,bj),bis in bycol.items():
        if len(bis)>=2:
            for bi in range(min(bis),max(bis)+1): fill(bi,bj,col)
    for (col,bi),bjs in byrow.items():
        if len(bjs)>=2:
            for bj in range(min(bjs),max(bjs)+1): fill(bi,bj,col)
    return out

